// 0.2.1 as it ships: the base target (same code, tasks and memory) with the 0.2.1 `agentos init` rule text and the
// MCP servers run from this checkout's dist/ — npm still serves 0.2.0, whose supersearch_text description differs.
// CLAUDE.md is generated by this checkout's dist/ in every target, so it already carries the 0.2.1 tools note.
// Run after `npm run compile`.
import { fileURLToPath } from "node:url";
import base from "./agentos.mjs";

const cli = fileURLToPath(new URL("../../dist/cli.js", import.meta.url)).replace(/\\/g, "/");

let config = base.agentos.config;
for (const [from, to] of [
  ["Use the codegraph/supersearch MCP tools", "Use the codegraph MCP tools"],
  ...["memory", "supersearch", "codegraph"].map((s) => [
    `command: npx\n    args: ["-y", "@basit0090/agent-os", "mcp", "${s}"]`,
    `command: node\n    args: ["${cli}", "mcp", "${s}"]`,
  ]),
]) {
  if (!config.includes(from)) throw new Error(`base config changed: ${from}`);
  config = config.replace(from, to);
}

export default { ...base, name: "agentos-0.2.1", agentos: { ...base.agentos, config } };
